#!/usr/bin/env python3
"""Filter and aggregate RFC-4180 CSV files using only the standard library."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Sequence


def column_name(value: str) -> str:
    if not value:
        raise argparse.ArgumentTypeError("column names must not be empty")
    return value


def filter_expression(value: str) -> tuple[str, str]:
    if "=" not in value:
        raise argparse.ArgumentTypeError("filters must have the form COLUMN=VALUE")
    column, expected = value.split("=", 1)
    if not column:
        raise argparse.ArgumentTypeError("filter column must not be empty")
    return column, expected


def parse_arguments(argv: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Filter and aggregate CSV data.")
    parser.add_argument("input", help="input CSV file")
    parser.add_argument("--where", action="append", type=filter_expression, default=[], metavar="COLUMN=VALUE")
    parser.add_argument("--group-by", type=column_name, metavar="COLUMN")
    parser.add_argument("--sum", dest="sum_column", type=column_name, metavar="COLUMN")
    parser.add_argument("--avg", dest="avg_column", type=column_name, metavar="COLUMN")
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)
    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    return args


def read_csv(filename: str) -> tuple[list[str], list[dict[str, str]]]:
    try:
        with Path(filename).open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source)
            try:
                headers = next(reader)
            except StopIteration:
                raise ValueError("input CSV is empty")
            if not headers or any(not header for header in headers):
                raise ValueError("CSV headers must be non-empty")
            if len(set(headers)) != len(headers):
                raise ValueError("CSV headers must be unique")

            rows = []
            for row_number, row in enumerate(reader, start=2):
                if len(row) != len(headers):
                    raise ValueError(
                        f"row {row_number} has {len(row)} fields; expected {len(headers)}"
                    )
                rows.append(dict(zip(headers, row)))
            return headers, rows
    except OSError as error:
        raise ValueError(f"could not read input file: {error}") from error
    except csv.Error as error:
        raise ValueError(f"malformed CSV: {error}") from error


def require_columns(headers: list[str], columns: Sequence[str]) -> None:
    for column in columns:
        if column not in headers:
            raise ValueError(f"unknown column: {column}")


def format_decimal(value: Decimal) -> str:
    value = value.normalize()
    if value == 0:
        return "0"
    return format(value, "f")


def numeric_value(value: str, row_number: int, column: str) -> Decimal:
    if not value:
        raise ValueError(f"invalid numeric value at row {row_number}, column {column}: blank")
    try:
        parsed = Decimal(value)
    except InvalidOperation as error:
        raise ValueError(f"invalid numeric value at row {row_number}, column {column}: {value!r}") from error
    if not parsed.is_finite():
        raise ValueError(f"invalid numeric value at row {row_number}, column {column}: {value!r}")
    return parsed


def aggregate(rows: list[dict[str, str]], group_by: str, sum_column: str | None, avg_column: str | None) -> tuple[list[str], list[dict[str, str]]]:
    groups: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        groups[row[group_by]].append(row)

    output_headers = [group_by]
    if sum_column:
        output_headers.append(f"sum_{sum_column}")
    if avg_column:
        output_headers.append(f"avg_{avg_column}")

    results = []
    for group, group_rows in sorted(groups.items()):
        result = {group_by: group}
        if sum_column:
            total = sum(
                (numeric_value(row[sum_column], index + 2, sum_column) for index, row in enumerate(group_rows)),
                Decimal("0"),
            )
            result[f"sum_{sum_column}"] = format_decimal(total)
        if avg_column:
            values = [numeric_value(row[avg_column], index + 2, avg_column) for index, row in enumerate(group_rows)]
            result[f"avg_{avg_column}"] = format_decimal(sum(values, Decimal("0")) / len(values))
        results.append(result)
    return output_headers, results


def write_output(headers: list[str], rows: list[dict[str, str]], output_format: str) -> None:
    if output_format == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False)
        sys.stdout.write("\n")
        return
    writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)


def main(argv: Sequence[str] | None = None) -> int:
    try:
        args = parse_arguments(sys.argv[1:] if argv is None else argv)
        headers, rows = read_csv(args.input)
        require_columns(headers, [column for column, _ in args.where])
        require_columns(headers, [column for column in (args.group_by, args.sum_column, args.avg_column) if column])
        rows = [row for row in rows if all(row[column] == value for column, value in args.where)]
        if args.group_by:
            headers, rows = aggregate(rows, args.group_by, args.sum_column, args.avg_column)
        write_output(headers, rows, args.output)
        return 0
    except (ValueError, argparse.ArgumentError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
